cd /app/trial/agent
python3 -I -c "
import json
with open('trajectory.json') as f:
    data = json.load(f)
steps = data['steps']
for s in steps:
    for tc in s.get('tool_calls', []):
        fn = tc.get('function_name')
        args = tc.get('arguments', {})
        if fn == 'Bash':
            print(s['step_id'], fn, '|', str(args.get('command'))[:200].replace(chr(10),' '))
        elif fn in ('Edit','Write'):
            print(s['step_id'], fn, '|', args.get('file_path'))
        else:
            print(s['step_id'], fn, '|', str(args)[:150])
"

